v1.yaml:
rules:
  - id: policy-routing
    priority: 5
    when: {field: hostname, op: eq, value: socai2-policy-host}
    then: {set_severity: high, route_to: cloud, tag: policy-v1}
  - id: policy-maintenance
    priority: 10
    when: {field: username, op: eq, value: socai2-policy-maint}
    then: {suppress: true}

v2.yaml:
rules:
  - id: policy-routing
    priority: 5
    when: {field: hostname, op: eq, value: socai2-policy-host}
    then: {set_severity: critical, route_to: identity, tag: policy-v2}
  - id: policy-maintenance
    priority: 10
    when: {field: username, op: eq, value: socai2-policy-maint}
    then: {suppress: true}

